import { GRSymbolEvent } from './../types/index';
import { Rectangle, Container, Graphics, Texture } from 'pixi.js';
import { GRService } from '.';
import { IParentReelData, ISymbolData, ISymbolSettings } from '../types';
import { GREvents } from '../events';
export abstract class GRSymbolView extends Container {

    public eventFire: GRSymbolEvent;

    public symbolData: ISymbolData = {
        index: 0,
        skin: 0,
        onScreen: false,
    };
    public parentReelData: IParentReelData = {
        index: 0,
        speed: 0,
        spinning: false,
    };
    private _background: Graphics;
    private _service: GRService;
    private _events: GREvents;

    constructor() {
        super();
        // initialize event system
        this._events = new GREvents();
        this.eventFire = { symbolEvent: this._events.symbolEvents };
    }

    public dynamicBlurTexture(defaultState: Texture, blurState: Texture, speedTrigger: number): Texture {
        // returns a blur texture or default texure depending on a set speed
        return this.parentReelData.speed >= speedTrigger ? blurState : defaultState;
    }

    public initialiseSymbol(service: GRService) {

        if (this._service) {
            console.warn('symbol has already been initialised');
            return;
        }
        this._service = service;

        // create padding to keep spacing equal.
        this._background = new Graphics();
        this.addChild(this._background);
        const width = this.symbolSettings.frameTransfrom.width;
        const height = this.symbolSettings.frameTransfrom.height;
        const backgroundBounds: Rectangle = new Rectangle(-width * 0.5, -height * 0.5, width, height);
        this._background.drawRect(backgroundBounds.x, backgroundBounds.y, backgroundBounds.width, backgroundBounds.height);
        this._background.cacheAsBitmap = true;
        this._background.hitArea = backgroundBounds;
    }

    public preDraw(): void { /* to be defined in game */ }
    public postDraw(): void { /* to be dedined in game */ }
    public abstract setStaticSkin(): void;
    public abstract setAnimationSkin(): void;

    public get symbolSettings(): ISymbolSettings {
        return this._service.symbolSettings;
    }
}
